package com.amicbeam.beyondcraftlines.common.network;
import com.amicbeam.beyondcraftlines.BeyondCraftlines;import com.amicbeam.beyondcraftlines.common.dashboard.*;import com.amicbeam.beyondcraftlines.common.menu.DashboardConfigMenu;import com.amicbeam.beyondcraftlines.common.runtime.CraftlineDashboardBlockEntity;import com.wintercogs.beyonddimensions.api.storage.key.IStackKey;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.*;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;import net.minecraft.server.level.ServerPlayer;import net.neoforged.neoforge.network.handling.IPayloadContext;import org.jetbrains.annotations.NotNull;
public record ConfigureDashboardPayload(BlockPos position,IStackKey<?> target,long desired,String stockMode,String redstoneMode)implements CustomPacketPayload{public static final Type<ConfigureDashboardPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(BeyondCraftlines.MOD_ID,"configure_dashboard"));public static final StreamCodec<RegistryFriendlyByteBuf,ConfigureDashboardPayload> STREAM_CODEC=StreamCodec.composite(BlockPos.STREAM_CODEC,ConfigureDashboardPayload::position,IStackKey.STREAM_CODEC,ConfigureDashboardPayload::target,ByteBufCodecs.VAR_LONG,ConfigureDashboardPayload::desired,ByteBufCodecs.stringUtf8(16),ConfigureDashboardPayload::stockMode,ByteBufCodecs.stringUtf8(16),ConfigureDashboardPayload::redstoneMode,ConfigureDashboardPayload::new);public static void handle(ConfigureDashboardPayload p,IPayloadContext c){c.enqueueWork(()->{if(c.player() instanceof ServerPlayer player&&player.containerMenu instanceof DashboardConfigMenu menu&&menu.position().equals(p.position())&&player.level().getBlockEntity(p.position()) instanceof CraftlineDashboardBlockEntity d)d.configure(player,p.target(),p.desired(),DashboardStockMode.byId(p.stockMode()),DashboardRedstoneMode.byId(p.redstoneMode()));});}@Override public @NotNull Type<? extends CustomPacketPayload> type(){return TYPE;}}
